{"command":"$mainWindowXaml = Get-Content -LiteralPath "src\StreamTranslator.App\MainWindow.xaml" -Raw
$mainWindowCode = Get-Content -LiteralPath "src\StreamTranslator.App\MainWindow.xaml.cs" -Raw
$floatingWindowCode = Get-Content -LiteralPath "src\StreamTranslator.App\FloatingSubtitleWindow.xaml.cs" -Raw

$checks = @(
    @{ Name = "Mica"; Ok = ($mainWindowXaml -match 'WindowBackdropType="Mica"') }
    @{ Name = "HomeIssuesCard"; Ok = ($mainWindowXaml -match '<Border x:Name="HomeIssuesCard"[\s\S]*AutomationProperties\.AutomationId="HomeIssuesPanel"') }
    @{ Name = "SubtitleGroupLabel"; Ok = ($mainWindowXaml -match 'Text="显示字幕数"') }
    @{ Name = "WorkArea40Percent"; Ok = ($floatingWindowCode -match 'WorkArea\.Height \* 0\.4') }
    @{ Name = "ChromeMeasureAndTrim"; Ok = (($floatingWindowCode -match 'Chrome\.Measure\([\s\S]*double\.PositiveInfinity') -and ($floatingWindowCode -match 'Entries\.RemoveAt\(0\)')) }
    @{ Name = "VisibleGroupsChanged"; Ok = ($mainWindowCode -match 'OnFloatingVisibleGroupsChanged') }
)
