{"command":"$exe = (Resolve-Path "src\StreamTranslator.App\bin\Debug\net10.0-windows\StreamTranslator.exe").Path
$p = Start-Process -FilePath $exe -WorkingDirectory (Split-Path $exe) -PassThru
Start-Sleep -Seconds 3
$p.Refresh()
$exited = $p.HasExited
$exitCode = if ($exited) { $p.ExitCode } else { -1 }
$title = if (-not $exited) { $p.MainWindowTitle } else { "" }
Write-Host "HasExited=$exited ExitCode=$exitCode MainWindowTitle='$title'"
if (-not $exited) {
    $null = $p.CloseMainWindow()
    Start-Sleep -Seconds 2
    $p.Refresh()
    if (-not $p.HasExited) { Stop-Process -Id $p.Id -Force }
}
if ($exited) { exit 1 }","description":"Launch StreamTranslator debug exe to verify XAML parses and runs cleanly"}

